class SyncFacebook(SyncAPIResource):
    """The Facebook endpoints, blocking.

    Reached as :attr:`~tapline.SyncTaplineClient.facebook`. Anywhere a method takes an
    enum it also takes the enum's raw value.

    Every method raises ``AuthenticationError`` when the API key is rejected,
    ``InsufficientCreditsError`` when the account cannot pay for the call,
    ``RateLimitError`` once automatic retries are exhausted, and
    ``InternalServerError`` when Tapline or the upstream site fails.
    """

    def list_comments(
        self,
        *,
        feedback_id: str,
        cursor: str = "",
        sort: CommentSortParam = "relevant",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> FacebookCommentsPage:
        """List the comments on a post, photo, video or reel. Costs 3 credits.

        Args:
            feedback_id: `feedback_id` of a post, photo, video or reel.
            cursor: `pagination.next_cursor` from the previous page; empty for the
                first page.
            sort: Most relevant, newest first, or all comments.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.facebook.FacebookCommentsPage`.
        """
        return self._send(
            _list_comments(feedback_id=feedback_id, cursor=cursor, sort=sort), timeout=timeout
        )

    def list_comment_replies(
        self,
        comment_id: str,
        *,
        cursor: str,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> FacebookRepliesPage:
        """List the replies to a comment, 10 per page. Costs 3 credits.

        Args:
            comment_id: The comment's `id`.
            cursor: The comment's `replies_cursor`, then `pagination.next_cursor`.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.facebook.FacebookRepliesPage`.
        """
        return self._send(_list_comment_replies(comment_id, cursor=cursor), timeout=timeout)

    def list_city_events(
        self,
        city_id: str,
        *,
        cursor: str = "",
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> FacebookCityEventsPage:
        """List the events Facebook suggests in a city, 12 per page. Costs 3 credits.

        Args:
            city_id: A city page id: `locations[].city_id` from
                `/marketplace/locations`.
            cursor: `pagination.next_cursor` from the previous page; empty for the
                first page.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.facebook.FacebookCityEventsPage`.
        """
        return self._send(_list_city_events(city_id, cursor=cursor), timeout=timeout)

    def search_events(
        self,
        *,
        query: str,
        category_id: str | None = None,
        city_id: str | None = None,
        cursor: str = "",
        date: EventDateRangeParam | None = None,
        end_date: str | None = None,
        start_date: str | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> FacebookEventSearchPage:
        """Search public events by keyword. Costs 3 credits.

        Args:
            query: Search text.
            category_id: An event category: `param_value` of a `category_id` option
                in the answer's `filters[]`.
            city_id: Only events in this city: `locations[].city_id` from
                `/marketplace/locations`.
            cursor: `pagination.next_cursor` from the previous page; empty for the
                first page.
            date: A day range counted from today, as in the `date` options of the
                answer's `filters[]`. Send this or `start_date` and `end_date`.
            end_date: Last day of a custom range.
            start_date: First day of a custom range.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.facebook.FacebookEventSearchPage`.
        """
        return self._send(
            _search_events(
                query=query,
                category_id=category_id,
                city_id=city_id,
                cursor=cursor,
                date=date,
                end_date=end_date,
                start_date=start_date,
            ),
            timeout=timeout,
        )

